import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Alerts = ({weatherData}) => {
    if (weatherData.main.temp <= 0) return "❄️ Freezing temps - Frostbite risk!";
    
    if (weatherData.pop >= 0.8 && isWithinNextHour(weatherData.dt)) {
        const mins = getMinutesUntil(weatherData.dt);
        return `🌧️ Rain starting in ${mins} minutes - Seek cover!`;
      }
}

export default Alerts;
